import{_ as e,a as i}from"./chunks/image11.DgqECnCK.js";import{_ as o,o as A,c as a,ak as s}from"./chunks/framework.C7PCA8hc.js";const n="/projects/miniAutopro/en/latest/assets/image1.CcPqb3M7.webp",r="/projects/miniAutopro/en/latest/assets/image2.DQYoiBXh.webp",l="/projects/miniAutopro/en/latest/assets/image3.ChWjcIe2.webp",g="/projects/miniAutopro/en/latest/assets/image4.C3irya9W.webp",d="/projects/miniAutopro/en/latest/assets/image5.B6Ch3p8Y.webp",c="/projects/miniAutopro/en/latest/assets/image6.g8bCgBB9.webp",h="/projects/miniAutopro/en/latest/assets/image7.EsvF3lgT.webp",m="data:image/png;base64,",p="data:image/png;base64,",u="data:image/png;base64,",C="data:image/png;base64,",w="data:image/png;base64,",f="data:image/png;base64,",b="data:image/png;base64,",y="data:image/png;base64,",B="data:image/png;base64,",x="data:image/png;base64,",I="data:image/png;base64,",v="data:image/png;base64,",V="data:image/png;base64,",E="data:image/png;base64,",D="data:image/png;base64,",Q="data:image/png;base64,",S="/projects/miniAutopro/en/latest/assets/image17.h5rdtwDc.webp",N="/projects/miniAutopro/en/latest/assets/image1.BZ7Pi1SQ.webp",k="/projects/miniAutopro/en/latest/assets/image48.DTAuBUP7.webp",Y="/projects/miniAutopro/en/latest/assets/image51.BKi2Aus2.webp",X="/projects/miniAutopro/en/latest/assets/image49.CwNMYNtA.webp",O="data:image/png;base64,",G="/projects/miniAutopro/en/latest/assets/image3.B3I6B93c.webp",T="/projects/miniAutopro/en/latest/assets/image5.C3Xn2tEm.webp",W="/projects/miniAutopro/en/latest/assets/image21.Be4whjDU.webp",K="data:image/png;base64,",U="/projects/miniAutopro/en/latest/assets/image7.L6tVNQWZ.webp",R="data:image/png;base64,",j="/projects/miniAutopro/en/latest/assets/image9.Cpu5YUB3.webp",z="data:image/png;base64,",P="/projects/miniAutopro/en/latest/assets/image11.BIaklkZZ.webp",tt=JSON.parse('{"title":"2. Development Environment Setup","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Development Environment Setup.md","filePath":"docs/2. Development Environment Setup.md"}'),M={name:"docs/2. Development Environment Setup.md"};function Z(L,t,F,q,H,J){return A(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="_2-development-environment-setup" tabindex="-1">2. Development Environment Setup <a class="header-anchor" href="#_2-development-environment-setup" aria-label="Permalink to &quot;2. Development Environment Setup&quot;">​</a></h1><h2 id="_2-1-arduino-ide-installation-and-interface-introduction" tabindex="-1">2.1 Arduino IDE Installation and Interface Introduction <a class="header-anchor" href="#_2-1-arduino-ide-installation-and-interface-introduction" aria-label="Permalink to &quot;2.1 Arduino IDE Installation and Interface Introduction&quot;">​</a></h2><h3 id="_2-1-1-arduino-ide-installation" tabindex="-1">2.1.1 Arduino IDE Installation <a class="header-anchor" href="#_2-1-1-arduino-ide-installation" aria-label="Permalink to &quot;2.1.1 Arduino IDE Installation&quot;">​</a></h3><p>Arduino IDE is a powerful software suite specifically designed for Arduino microcontrollers. The installation procedure remains consistent across versions. This section demonstrates the installation process using Arduino IDE 2.2.1 for Windows as an example.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>For the macOS installation method, refer to the documentation in the directory of this section.</strong></p></div><ol><li>In the archive package under <a href="https://drive.google.com/drive/folders/1HO8c8pUdxdfOjXVc3AM88DD8BRd0aqfo?usp=sharing" target="_blank" rel="noreferrer">2. Software Tools &amp; Programs/1. Arduino Development Environment Setup</a>, double-click <strong>ArduinoIDE-2.2.1.exe</strong>, as shown below. To download the latest software version, visit the official Arduino website at <a href="https://www.arduino.cc/en/software" target="_blank" rel="noreferrer">https://www.arduino.cc/en/software</a>.</li></ol><img loading="lazy" height="138" width="118" src="'+n+'" class="common_img" style="width:150px;"><ol start="2"><li>Click <strong>I Agree</strong> to proceed with the installation.</li></ol><img loading="lazy" height="362" width="503" src="'+r+'" class="common_img" style="width:600px;"><ol start="3"><li>Retain the default settings and click <strong>Next</strong> to proceed to the next step.</li></ol><img loading="lazy" height="362" width="503" src="'+l+'" class="common_img" style="width:600px;"><ol start="4"><li>Click <strong>Browse</strong> to select the target installation path, then click <strong>Install</strong> to start the installation.</li></ol><img loading="lazy" height="362" width="503" src="'+g+'" class="common_img" style="width:600px;"><ol start="5"><li>Wait for the installation to finish.</li></ol><img loading="lazy" height="362" width="503" src="'+d+'" class="common_img" style="width:600px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If prompted to install device drivers during the installation process, check &quot;Always trust software from Arduino LLC&quot; and click Install.</strong></p></div><ol start="6"><li>After the installation is complete, click <strong>Finish</strong>.</li></ol><img loading="lazy" height="362" width="503" src="'+c+'" class="common_img" style="width:600px;"><h3 id="_2-1-2-interface-layout-overview" tabindex="-1">2.1.2 Interface Layout Overview <a class="header-anchor" href="#_2-1-2-interface-layout-overview" aria-label="Permalink to &quot;2.1.2 Interface Layout Overview&quot;">​</a></h3><p>The main interface of Arduino IDE is shown below, divided into five primary sections:</p><img loading="lazy" height="578" width="749" src="'+h+'" class="common_img" style="width:800px;"><ol><li><strong>Menu Bar</strong>: Configures global Arduino IDE settings and preferences.</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="19" width="39" src="'+m+'" class="common_img"></td><td style="text-align:left;">Creates or opens project files, and configures interface preferences.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="19" width="39" src="'+p+'" class="common_img"></td><td style="text-align:left;">Provides text editing options, including code commenting, indenting, and searching.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="19" width="39" src="'+u+'" class="common_img"></td><td style="text-align:left;">Configures sketch settings, compiles and runs programs, and imports library files.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="19" width="39" src="'+C+'" class="common_img"></td><td style="text-align:left;">Selects development boards and communication ports, and retrieves board information.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="19" width="55" src="'+w+'" class="common_img"></td><td style="text-align:left;">Provides introductory documentation and troubleshooting guidance.</td></tr></tbody></table><ol start="2"><li><strong>Toolbar</strong>: Houses frequently used project development tools, including sketch verification, upload, and serial monitoring.</li></ol><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="38" width="41" src="'+f+'" class="common_img"></td><td style="text-align:left;">Verifies and compiles the current sketch to check for syntax errors.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="38" width="40" src="'+b+'" class="common_img"></td><td style="text-align:left;">Uploads compiled programs to the connected Arduino controller.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="37" width="40" src="'+y+'" class="common_img"></td><td style="text-align:left;">Initiates real-time debugging for supported development boards.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="39" width="249" src="'+B+'" class="common_img"></td><td style="text-align:left;">Selects the connected development board and communication port.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="36" width="33" src="'+x+'" class="common_img"></td><td style="text-align:left;">Opens Serial Plotter to visualize serial data in real-time graphs.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="35" width="39" src="'+I+'" class="common_img"></td><td style="text-align:left;">Opens Serial Monitor to display serial communication data.</td></tr></tbody></table><ol start="3"><li><p><strong>Editor</strong>: The primary workspace for writing and editing program code.</p></li><li><p><strong>Status Bar</strong>: Displays editor status information, including the cursor line and column numbers and the connected board details.</p></li><li><p><strong>Sidebar</strong>: The core navigation panel of Arduino IDE, providing access to the sketchbook, board managers, library installation, and debugging tools.</p></li></ol><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:left;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="46" width="44" src="'+v+'" class="common_img"></td><td style="text-align:left;">Displays sketches and files contained in the sketchbook.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="44" width="47" src="'+V+'" class="common_img"></td><td style="text-align:left;">Opens Boards Manager to search and install board packages.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="45" width="43" src="'+E+'" class="common_img"></td><td style="text-align:left;">Opens Library Manager to search, install, and manage libraries.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="44" width="41" src="'+D+'" class="common_img"></td><td style="text-align:left;">Provides project debugging controls and breakpoints.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="42" width="42" src="'+Q+'" class="common_img"></td><td style="text-align:left;">Searches and replaces code variables and text strings.</td></tr></tbody></table><h2 id="_2-2-arduino-ide-settings-and-configuration" tabindex="-1">2.2 Arduino IDE Settings and Configuration <a class="header-anchor" href="#_2-2-arduino-ide-settings-and-configuration" aria-label="Permalink to &quot;2.2 Arduino IDE Settings and Configuration&quot;">​</a></h2><h3 id="_2-2-1-setting-arduino-ide-display-language" tabindex="-1">2.2.1 Setting Arduino IDE Display Language <a class="header-anchor" href="#_2-2-1-setting-arduino-ide-display-language" aria-label="Permalink to &quot;2.2.1 Setting Arduino IDE Display Language&quot;">​</a></h3><ol><li>To configure the interface language, select <strong>File</strong> -&gt; <strong>Preferences</strong> in the Arduino IDE menu bar.</li></ol><img loading="lazy" height="564" width="779" src="'+S+'" class="common_img" style="width:800px;"><ol start="2"><li>In the pop-up window, locate the <strong>Language</strong> option to select the desired display language, then click <strong>OK</strong>.</li></ol><img loading="lazy" height="707" width="971" src="'+N+'" class="common_img" style="width:800px;"><h3 id="_2-2-2-esp32-package-installation" tabindex="-1">2.2.2 ESP32 Package Installation <a class="header-anchor" href="#_2-2-2-esp32-package-installation" aria-label="Permalink to &quot;2.2.2 ESP32 Package Installation&quot;">​</a></h3><ol><li><p>If an ESP32 board support package has been installed previously and its version is not 3.3.11, follow step 2 to remove the older version. If no package was installed previously, or if version 3.3.11 is already installed, proceed directly to step 3.</p></li><li><p>Removal methods:</p></li></ol><p>Enter <strong>%LOCALAPPDATA%/Arduino15/packages</strong> into the File Explorer address bar and press <strong>Enter</strong> to open the directory, then delete the <strong>esp32</strong> folder.</p><img loading="lazy" height="221" width="603" src="'+k+'" class="common_img" style="width:800px;"><p>Alternatively, click <strong>Boards Manager</strong> on the left sidebar of the Arduino IDE interface, search for <strong>esp32</strong>, and remove the existing package.</p><img loading="lazy" height="530" width="395" src="'+Y+'" class="common_img" style="width:500px;"><ol start="3"><li>Installation method: Locate <a href="https://drive.google.com/drive/folders/1HO8c8pUdxdfOjXVc3AM88DD8BRd0aqfo?usp=sharing" target="_blank" rel="noreferrer">2. Software Tools &amp; Programs/1. Arduino Development Environment Setup/ESP32 Chip Package</a>, open <strong>esp32_package_3.3.11_arduinome.exe</strong>, and wait for the installation process to complete.</li></ol><img loading="lazy" height="23" width="277" src="'+X+'" class="common_img" style="width:400px;"><ol start="4"><li>After the installation is complete, always select <strong>ESP32 Dev Module</strong> from the board list when compiling and uploading programs.</li></ol><img loading="lazy" height="47" width="597" src="'+O+'" class="common_img" style="width:600px;"><h3 id="_2-2-3-arduino-program-upload" tabindex="-1">2.2.3 Arduino Program Upload <a class="header-anchor" href="#_2-2-3-arduino-program-upload" aria-label="Permalink to &quot;2.2.3 Arduino Program Upload&quot;">​</a></h3><ol><li>This section demonstrates the upload process using a test routine that prints <strong>hiwonder</strong>. Under the same directory as this document, locate the <strong><a href="https://drive.google.com/drive/folders/1fzEhCytyDuxU4Rgm-TKrfAVo_qZsIYM8?usp=sharing" target="_blank" rel="noreferrer">03 _Demo/Demo</a></strong> folder and double-click to open <strong>Demo.ino</strong>.</li></ol><img loading="lazy" height="618" width="1054" src="'+G+'" class="common_img" style="width:800px;"><ol start="2"><li>Connect the ESP32 UNO board to the computer using a Type-C cable.</li></ol><img loading="lazy" height="550" width="826" src="'+e+'" class="common_img" style="width:800px;"><ol start="3"><li>Click the <strong>Select Board</strong> dropdown menu in the toolbar, then select the corresponding port. The assigned COM port number varies across computers and can be identified via Windows Device Manager. This section takes COM10 as an example.</li></ol><img loading="lazy" height="213" width="551" src="'+T+'" class="common_img" style="width:600px;"><ol start="4"><li>Search for <strong>esp32 dev module</strong>, select <strong>ESP32 Dev Module</strong>, and click <strong>OK</strong>.</li></ol><img loading="lazy" height="496" width="693" src="'+W+'" class="common_img" style="width:600px;"><ol start="5"><li>Click the Verify icon <img loading="lazy" height="38" width="41" src="'+K+'" class="inline-icon">to compile the sketch and verify that no syntax errors exist.</li></ol><img loading="lazy" height="1040" width="1920" src="'+U+'" class="common_img" style="width:800px;"><ol start="6"><li>Once compilation succeeds, click the Upload icon <img loading="lazy" height="37" width="39" src="'+R+'" class="inline-icon">to upload the program to the ESP32 UNO board.</li></ol><img loading="lazy" height="1040" width="1920" src="'+j+'" class="common_img" style="width:800px;"><ol start="7"><li>After the upload is complete, click the Serial Monitor icon <img loading="lazy" height="35" width="35" src="'+z+'" class="inline-icon">to open Serial Monitor. The terminal displays the printed string <strong>hiwonder</strong>, as shown below.</li></ol><img loading="lazy" height="618" width="1054" src="'+P+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If the upload fails, lower the upload baud rate to 115200 and re-upload the sketch.</strong></p></div><img loading="lazy" height="657" width="769" src="'+i+'" class="common_img" style="width:800px;">',60)])])}const et=o(M,[["render",Z]]);export{tt as __pageData,et as default};
